import { Component, OnInit } from '@angular/core';
import { Router, ActivatedRoute } from '@angular/router';
import { AuthService } from '../../services/auth.service';

@Component({
  selector: 'app-auth',
  templateUrl: './auth.component.html',
  styleUrls: ['./auth.component.css']
})
export class AuthComponent implements OnInit {
  isLoginTab = true;
  returnUrl = '/home';
  redirectReason = '';

  loginData = {
    email: '',
    password: ''
  };

  registerData = {
    name: '',
    email: '',
    password: '',
    phone: '',
    role: 'ROLE_USER' // Only customers can register
  };

  loading = false;
  errorMessage = '';
  successMessage = '';

  constructor(
    private authService: AuthService,
    private router: Router,
    private route: ActivatedRoute
  ) {}

  ngOnInit(): void {
    this.route.queryParams.subscribe(params => {
      if (params['returnUrl']) {
        this.returnUrl = params['returnUrl'];
      }
      if (params['reason']) {
        this.redirectReason = params['reason'];
      }
    });
  }

  switchTab(isLogin: boolean) {
    this.isLoginTab = isLogin;
    this.errorMessage = '';
    this.successMessage = '';
  }

  onLogin() {
    if (!this.loginData.email || !this.loginData.password) {
      this.errorMessage = 'Please enter both email and password.';
      return;
    }

    this.loading = true;
    this.errorMessage = '';
    this.authService.login(this.loginData).subscribe(res => {
      this.loading = false;
      if (res.success && res.data) {
        this.successMessage = res.message;
        const targetUrl = res.data.role === 'ROLE_ADMIN' ? '/order-tracker' : this.returnUrl;
        setTimeout(() => this.router.navigateByUrl(targetUrl), 800);
      } else {
        this.errorMessage = res.message || 'Login failed.';
      }
    });
  }

  onRegister() {
    if (!this.registerData.name || !this.registerData.email || !this.registerData.password) {
      this.errorMessage = 'Please fill out all required fields.';
      return;
    }

    this.loading = true;
    this.errorMessage = '';
    this.registerData.role = 'ROLE_USER'; // Customer signup only

    this.authService.register(this.registerData).subscribe(res => {
      this.loading = false;
      if (res.success) {
        this.successMessage = res.message;
        setTimeout(() => this.router.navigateByUrl(this.returnUrl), 800);
      } else {
        this.errorMessage = res.message;
      }
    });
  }
}
<div class="auth-page">
  <div class="auth-box">
    <div class="auth-header">
      <h2>Welcome to <span class="highlight">eKart</span></h2>
      <p>Sign in or create an account to manage your orders, track delivery status, or complete checkout.</p>
    </div>

    <!-- REDIRECT PROMPT FROM CHECKOUT -->
    <div class="alert alert-warning" *ngIf="redirectReason === 'checkout'">
      🔒 <strong>Authentication Required:</strong> Please sign in or create an account to proceed to payment and complete your order.
    </div>

    <!-- TAB HEADERS -->
    <div class="tab-header">
      <button [class.active]="isLoginTab" (click)="switchTab(true)">Sign In</button>
      <button [class.active]="!isLoginTab" (click)="switchTab(false)">Register Account</button>
    </div>

    <div class="alert alert-success" *ngIf="successMessage">
      ✅ {{ successMessage }}
    </div>
    <div class="alert alert-danger" *ngIf="errorMessage">
      ⚠️ {{ errorMessage }}
    </div>

    <!-- LOGIN FORM -->
    <form (ngSubmit)="onLogin()" *ngIf="isLoginTab" class="auth-form">
      <div class="form-group">
        <label>Email Address *</label>
        <input type="email" [(ngModel)]="loginData.email" name="email" required class="form-input" placeholder="e.g. user@ekart.com">
      </div>
      <div class="form-group">
        <label>Password *</label>
        <input type="password" [(ngModel)]="loginData.password" name="password" required class="form-input" placeholder="••••••••">
      </div>
      <div class="form-footer">
        <div class="demo-credentials">
          💡 Demo Accounts: 
          <div>• Customer: <strong>user@ekart.com</strong> / <strong>password123</strong></div>
          <div>• Admin: <strong>admin@ekart.com</strong> / <strong>password123</strong></div>
        </div>
      </div>
      <button type="submit" [disabled]="loading" class="btn btn-primary submit-btn">
        {{ loading ? 'Authenticating...' : 'Sign In' }}
      </button>
    </form>

    <!-- REGISTER FORM -->
    <form (ngSubmit)="onRegister()" *ngIf="!isLoginTab" class="auth-form">
      <div class="form-group">
        <label>Account Type *</label>
        <div class="role-selector">
          <label class="role-option" [class.selected]="registerData.role === 'ROLE_USER'">
            <input type="radio" [(ngModel)]="registerData.role" name="role" value="ROLE_USER">
            👤 Customer Account
          </label>
          <label class="role-option" [class.selected]="registerData.role === 'ROLE_ADMIN'">
            <input type="radio" [(ngModel)]="registerData.role" name="role" value="ROLE_ADMIN">
            🛡️ Administrator Account
          </label>
        </div>
      </div>

      <div class="form-group">
        <label>Full Name *</label>
        <input type="text" [(ngModel)]="registerData.name" name="name" required class="form-input" placeholder="e.g. John Doe">
      </div>
      <div class="form-group">
        <label>Email Address *</label>
        <input type="email" [(ngModel)]="registerData.email" name="email" required class="form-input" placeholder="e.g. john@example.com">
      </div>
      <div class="form-group">
        <label>Password *</label>
        <input type="password" [(ngModel)]="registerData.password" name="password" required class="form-input" placeholder="Create password (min 6 chars)">
      </div>
      <div class="form-group">
        <label>Phone Number</label>
        <input type="tel" [(ngModel)]="registerData.phone" name="phone" class="form-input" placeholder="e.g. +91 9876543210">
      </div>
      <button type="submit" [disabled]="loading" class="btn btn-primary submit-btn">
        {{ loading ? 'Creating Account...' : (registerData.role === 'ROLE_ADMIN' ? 'Register Admin Account' : 'Register Customer Account') }}
      </button>
    </form>
  </div>
</div>
